/* portrait framing: pull every camera back for the vinyl cast */
(() => { const K = 2.25; const sc1 = (c) => { c[2] += 2.0; c[4] *= K; c[5] *= K; c[6] *= K; }; for (const id in SC) { const c = SC[id].cam; if (!c) continue; if (typeof c[0] === 'number') sc1(c); else c.forEach(sc1); } })();
/* readability: figures turned fully sideways face the camera a little more */
(() => { const FIG = new Set(Object.keys(CAST).filter((k) => /^(bilbo|bilboO|frodo|sam|merry|pippin|gand|gandW|saru|thorin|dwarf|gollum|smeagol|deagol|troll|trollS|orc|uruk|azog|bolg|gking|naz|witch|elrond|legolas|tauriel|thran|elf|bard|bkid|master|man|hob|aragorn|arK|gimli|boromir|arwen|theoO|theo|eowyn|faramir|rider|gondor)$/.test(CAST[k][0])));
  for (const id in SC) for (const k in (SC[id].A || {})) { const a = SC[id].A[k]; if (!a || !FIG.has(k) || typeof a.f !== 'number' || a.on || a.sit) continue; if (a.f >= 80 && a.f <= 120) a.f = 62; else if (a.f <= -80 && a.f >= -120) a.f = -62; } })();
